CREATE INDEX workflow_tasks_device ON inspection_tasks(asset_id,planned_at,status);
CREATE INDEX workflow_defects_device ON defects(asset_id,record_id,status);
CREATE UNIQUE INDEX workflow_one_record_per_device_task ON inspection_records(task_id,asset_id) WHERE task_id IS NOT NULL AND task_id<>'';
CREATE TRIGGER workflow_task_insert BEFORE INSERT ON inspection_tasks BEGIN SELECT CASE WHEN NEW.asset_id IS NULL OR NOT EXISTS(SELECT 1 FROM assets WHERE id=NEW.asset_id AND active=1) THEN RAISE(ABORT,'Task requires an active device') END; SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM users WHERE id=NEW.assignee_id AND active=1 AND password_hash<>'') THEN RAISE(ABORT,'Task requires an active assignee') END; END;
CREATE TRIGGER workflow_task_update BEFORE UPDATE ON inspection_tasks BEGIN SELECT CASE WHEN NEW.asset_id IS NOT NULL AND NEW.asset_id<>'' AND NOT EXISTS(SELECT 1 FROM assets WHERE id=NEW.asset_id) THEN RAISE(ABORT,'Task device missing') END; SELECT CASE WHEN NEW.assignee_id IS NOT NULL AND NEW.assignee_id<>'' AND NOT EXISTS(SELECT 1 FROM users WHERE id=NEW.assignee_id) THEN RAISE(ABORT,'Task assignee missing') END; SELECT CASE WHEN EXISTS(SELECT 1 FROM inspection_records WHERE task_id=OLD.id AND asset_id<>NEW.asset_id) THEN RAISE(ABORT,'Task device conflicts with existing records') END; END;
CREATE TRIGGER workflow_record_insert BEFORE INSERT ON inspection_records BEGIN SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM assets WHERE id=NEW.asset_id) THEN RAISE(ABORT,'Record device missing') END; SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM inspection_tasks WHERE id=NEW.task_id AND status='in_progress' AND (asset_id=NEW.asset_id OR asset_id IS NULL OR asset_id='')) THEN RAISE(ABORT,'Start the matching task before creating a record') END; END;
CREATE TRIGGER workflow_record_update BEFORE UPDATE ON inspection_records BEGIN SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM assets WHERE id=NEW.asset_id) THEN RAISE(ABORT,'Record device missing') END; SELECT CASE WHEN NEW.task_id IS NOT NULL AND NEW.task_id<>'' AND NOT EXISTS(SELECT 1 FROM inspection_tasks WHERE id=NEW.task_id AND (asset_id=NEW.asset_id OR asset_id IS NULL OR asset_id='')) THEN RAISE(ABORT,'Record task and device mismatch') END; SELECT CASE WHEN EXISTS(SELECT 1 FROM defects WHERE record_id=OLD.id AND asset_id<>NEW.asset_id) THEN RAISE(ABORT,'Record device conflicts with defect source') END; END;
CREATE TRIGGER workflow_defect_insert BEFORE INSERT ON defects BEGIN SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM assets WHERE id=NEW.asset_id) THEN RAISE(ABORT,'Defect device missing') END; SELECT CASE WHEN NEW.record_id IS NOT NULL AND NEW.record_id<>'' AND NOT EXISTS(SELECT 1 FROM inspection_records WHERE id=NEW.record_id AND asset_id=NEW.asset_id) THEN RAISE(ABORT,'Defect record and device mismatch') END; SELECT CASE WHEN NEW.assignee_id IS NOT NULL AND NEW.assignee_id<>'' AND NOT EXISTS(SELECT 1 FROM users WHERE id=NEW.assignee_id) THEN RAISE(ABORT,'Defect assignee missing') END; END;
CREATE TRIGGER workflow_defect_update BEFORE UPDATE ON defects BEGIN SELECT CASE WHEN NEW.asset_id<>OLD.asset_id OR COALESCE(NEW.record_id,'')<>COALESCE(OLD.record_id,'') THEN RAISE(ABORT,'Defect source is immutable') END; SELECT CASE WHEN NEW.assignee_id IS NOT NULL AND NEW.assignee_id<>'' AND NOT EXISTS(SELECT 1 FROM users WHERE id=NEW.assignee_id) THEN RAISE(ABORT,'Defect assignee missing') END; END;
CREATE TRIGGER workflow_attachment_insert BEFORE INSERT ON attachments BEGIN SELECT CASE WHEN NEW.record_id IS NOT NULL AND NEW.record_id<>'' AND NOT EXISTS(SELECT 1 FROM inspection_records WHERE id=NEW.record_id) THEN RAISE(ABORT,'Attachment record missing') END; SELECT CASE WHEN NEW.defect_id IS NOT NULL AND NEW.defect_id<>'' AND NOT EXISTS(SELECT 1 FROM defects WHERE id=NEW.defect_id) THEN RAISE(ABORT,'Attachment defect missing') END; SELECT CASE WHEN NEW.record_id IS NOT NULL AND NEW.record_id<>'' AND NEW.defect_id IS NOT NULL AND NEW.defect_id<>'' AND NOT EXISTS(SELECT 1 FROM defects WHERE id=NEW.defect_id AND record_id=NEW.record_id) THEN RAISE(ABORT,'Attachment sources mismatch') END; END;
CREATE TRIGGER workflow_task_delete BEFORE DELETE ON inspection_tasks WHEN EXISTS(SELECT 1 FROM inspection_records WHERE task_id=OLD.id) BEGIN SELECT RAISE(ABORT,'Task has inspection history'); END;
CREATE TRIGGER workflow_asset_delete BEFORE DELETE ON assets WHEN EXISTS(SELECT 1 FROM inspection_tasks WHERE asset_id=OLD.id) OR EXISTS(SELECT 1 FROM inspection_records WHERE asset_id=OLD.id) OR EXISTS(SELECT 1 FROM defects WHERE asset_id=OLD.id) BEGIN SELECT RAISE(ABORT,'Device has business history'); END;
CREATE TRIGGER workflow_record_delete BEFORE DELETE ON inspection_records WHEN EXISTS(SELECT 1 FROM defects WHERE record_id=OLD.id) OR EXISTS(SELECT 1 FROM attachments WHERE record_id=OLD.id) BEGIN SELECT RAISE(ABORT,'Record has evidence or defects'); END;
CREATE TRIGGER workflow_defect_delete BEFORE DELETE ON defects WHEN EXISTS(SELECT 1 FROM defect_events WHERE defect_id=OLD.id) OR EXISTS(SELECT 1 FROM attachments WHERE defect_id=OLD.id) BEGIN SELECT RAISE(ABORT,'Defect has lifecycle history'); END;
CREATE TRIGGER workflow_item_insert BEFORE INSERT ON inspection_check_items WHEN NOT EXISTS(SELECT 1 FROM inspection_records WHERE id=NEW.record_id) BEGIN SELECT RAISE(ABORT,'Check item record missing'); END;
CREATE TRIGGER workflow_item_update BEFORE UPDATE ON inspection_check_items WHEN NOT EXISTS(SELECT 1 FROM inspection_records WHERE id=NEW.record_id) BEGIN SELECT RAISE(ABORT,'Check item record missing'); END;
CREATE TRIGGER workflow_event_insert BEFORE INSERT ON defect_events WHEN NOT EXISTS(SELECT 1 FROM defects WHERE id=NEW.defect_id) BEGIN SELECT RAISE(ABORT,'Defect event parent missing'); END;
UPDATE schema_meta SET version=8;
